import sys
from collections import deque

RANK = {r: i for i, r in enumerate('A23456789TJQK', 1)}
def fits(card, top):
    return RANK[card[0]] + 1 == RANK[top[0]] and ((card[1] in 'DH') != (top[1] in 'DH'))
def play(hand, piles):
    moved = False
    while hand:
        for i, card in enumerate(hand):
            if card[0] == 'K':
                destination = next((p for p in (1, 3, 5, 7) if not piles[p]), None)
            else:
                destination = next((p for p in range(8) if piles[p] and fits(card, piles[p][-1])), None)
            if destination is not None:
                piles[destination].append(hand.pop(i))
                moved = True
                break
        else:
            break
    return moved
lines = sys.stdin.read().splitlines()
hands = [lines[0].split(), lines[1].split()]
draw = deque(' '.join(lines[2:]).split())
piles = [[] for _ in range(8)]
for p in (0, 2, 4, 6):
    piles[p].append(draw.popleft())
player = idle = 0
while idle < 2:
    changed = play(hands[player], piles)
    if draw:
        hands[player].append(draw.popleft())
        changed = True
    idle = 0 if changed else idle + 1
    player ^= 1
print(*(pile[-1] if pile else 'E' for pile in piles))
